select 
from expert_task_conflict_confirmation
where external_task_id = #{externalTaskId}
  and expert_user_id = #{userId}
  and service_start = #{serviceStart}
  and service_end = #{serviceEnd}
limit 1

select 
from expert_task_conflict_confirmation
where external_task_id = #{externalTaskId}
  and expert_user_id = #{userId}
  and status = 'CONFIRMED'
  and service_start < #{serviceEnd}
  and service_end > #{serviceStart}
order by confirmed_at desc, confirmation_id desc
limit 1

select 
from expert_task_conflict_confirmation
where external_task_id = #{externalTaskId}
  and expert_user_id = #{userId}
  and service_start < #{serviceEnd}
  and service_end > #{serviceStart}
order by request_time desc, confirmation_id desc
limit 1

select 
from expert_task_conflict_confirmation
where expert_user_id = #{userId}

    and status = #{status}

order by request_time desc, confirmation_id desc

mapper.update:
update expert_task_conflict_confirmation
set status = #{acceptanceStatus},
    conflict_status = #{conflictStatus},
    statement = #{statement},
    confirmed_at = sysdate(),
    version = version + 1
where confirmation_id = #{confirmationId}
  and expert_user_id = #{userId}
  and status = 'PENDING'
  and version = #{version}
